export class DivineAudio {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.music = null;
    this.sfx = null;
    this.started = false;
    this.muted = true;
    this.step = 0;
    this.nextTime = 0;
    this.timer = null;
    this.noiseBuffer = null;
    this.distortion = null;
  }

  async unlock() {
    if (!this.ctx) this.build();
    if (this.ctx.state === "suspended") {
      try { await this.ctx.resume(); } catch { /* gesture required */ }
    }
    if (!this.started) this.start();
    if (this.muted) this.setMuted(false);
  }

  build() {
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    const ctx = (this.ctx = new Ctx());

    const comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -20;
    comp.knee.value = 24;
    comp.ratio.value = 4;
    comp.attack.value = 0.004;
    comp.release.value = 0.24;

    this.master = ctx.createGain();
    this.master.gain.value = 0.0001;
    this.master.connect(comp).connect(ctx.destination);

    this.music = ctx.createGain();
    this.music.gain.value = 0.5;
    this.music.connect(this.master);

    this.sfx = ctx.createGain();
    this.sfx.gain.value = 0.85;
    this.sfx.connect(this.master);

    this.delay = ctx.createDelay(1.5);
    this.delay.delayTime.value = STEP * 3;
    const feedback = ctx.createGain();
    feedback.gain.value = 0.32;
    const wet = ctx.createGain();
    wet.gain.value = 0.2;
    this.delay.connect(feedback).connect(this.delay);
    this.delay.connect(wet).connect(this.music);

    this.noiseBuffer = ctx.createBuffer(1, ctx.sampleRate * 2, ctx.sampleRate);
    const data = this.noiseBuffer.getChannelData(0);
    for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;

    const curve = new Float32Array(1024);
    for (let i = 0; i < curve.length; i++) {
      const x = (i / (curve.length - 1)) * 2 - 1;
      curve[i] = ((3 + 12) * x * 20 * (Math.PI / 180)) / (Math.PI + 12 * Math.abs(x));
    }
    this.distortion = curve;
  }

  start() {
    if (!this.ctx || this.started) return;
    this.started = true;
    this.nextTime = this.ctx.currentTime + 0.08;
    this.step = 0;
    this.timer = setInterval(() => this.schedule(), 25);
  }

  schedule() {
    if (!this.ctx) return;
    if (this.nextTime < this.ctx.currentTime - 0.4) {
      this.nextTime = this.ctx.currentTime + 0.05;
    }
    while (this.nextTime < this.ctx.currentTime + 0.14) {
      this.playStep(this.step, this.nextTime);
      this.step = (this.step + 1) % 32;
      this.nextTime += STEP;
    }
  }

  setMuted(muted) {
    this.muted = muted;
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    this.master.gain.cancelScheduledValues(now);
    this.master.gain.setTargetAtTime(muted ? 0.0001 : 0.72, now, 0.08);
  }

  toggle() {
    if (this.muted) this.unlock();
    else this.setMuted(true);
    return !this.muted;
  }

  playStep(step, time) {
    const s = step % 16;
    const bar = Math.floor(step / 16) % 4;
    const root = BAR_ROOTS[bar];
    const chord = BAR_CHORDS[bar];

    if (s % 4 === 0) {
      this.kick(time);
      this.duck(time);
    }
    if (s === 4 || s === 12) this.clap(time);
    if (s % 2 === 0) this.hat(time, s === 14 ? 0.06 : 0.028, s === 14);
    if (s % 2 === 1 && Math.random() > 0.55) this.hat(time, 0.014, false);

    if ([0, 3, 6, 8, 11, 14].includes(s)) {
      const octave = s === 6 || s === 14 ? 2 : 1;
      this.bass(time, root * octave, s === 11 ? 0.13 : 0.2);
    }

    const degree = chord[ARP[(step + bar * 3) % ARP.length] % chord.length];
    const arpFreq = midiToFreq(69 + Math.round(12 * Math.log2(root / 440)) + degree + 24);
    this.arp(time, arpFreq, 0.09);

    if (s === 0) this.pad(time, root, chord, 2.6);
    if (s === 8 && bar === 3) this.sparkle(time);
  }

  tone(time, freq, dur, opts = {}) {
    if (!this.ctx) return;
    const {
      type = "sine",
      gain = 0.1,
      attack = 0.005,
      release = 0.1,
      slideTo = null,
      filter = null,
      filterQ = 1,
      dest = this.music,
      detune = 0,
    } = opts;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = type;
    o.frequency.setValueAtTime(Math.max(20, freq), time);
    if (slideTo) o.frequency.exponentialRampToValueAtTime(Math.max(20, slideTo), time + dur);
    if (detune) o.detune.value = detune;
    g.gain.setValueAtTime(0.0001, time);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), time + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, time + dur + release);
    let node = o;
    if (filter) {
      const f = this.ctx.createBiquadFilter();
      f.type = filter;
      f.frequency.value = typeof filter === "number" ? filter : 900;
      f.Q.value = filterQ;
      node.connect(f);
      node = f;
    }
    node.connect(g).connect(dest);
    o.start(time);
    o.stop(time + dur + release + 0.05);
  }

  noise(time, dur, opts = {}) {
    if (!this.ctx || !this.noiseBuffer) return;
    const { gain = 0.1, type = "highpass", freq = 8000, q = 0.8, dest = this.music, slideTo = null } = opts;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const f = this.ctx.createBiquadFilter();
    f.type = type;
    f.frequency.setValueAtTime(freq, time);
    if (slideTo) f.frequency.exponentialRampToValueAtTime(slideTo, time + dur);
    f.Q.value = q;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, time);
    g.gain.exponentialRampToValueAtTime(gain, time + 0.004);
    g.gain.exponentialRampToValueAtTime(0.0001, time + dur);
    src.connect(f).connect(g).connect(dest);
    src.start(time, Math.random() * 0.4);
    src.stop(time + dur + 0.02);
  }

  kick(time) {
    this.tone(time, 165, 0.22, { type: "sine", gain: 0.8, slideTo: 44, attack: 0.002, release: 0.08 });
    this.noise(time, 0.02, { gain: 0.12, type: "highpass", freq: 2200 });
  }

  clap(time) {
    this.noise(time, 0.11, { gain: 0.22, type: "bandpass", freq: 1500, q: 1.1 });
    this.noise(time + 0.012, 0.08, { gain: 0.14, type: "bandpass", freq: 2200, q: 1.4 });
  }

  hat(time, gain, open) {
    this.noise(time, open ? 0.16 : 0.035, { gain, type: "highpass", freq: 8600, q: 0.7 });
  }

  bass(time, freq, dur) {
    this.tone(time, freq, dur, { type: "sawtooth", gain: 0.18, filter: "lowpass", filterQ: 4, release: 0.05 });
    this.tone(time, freq / 2, dur, { type: "sine", gain: 0.22, release: 0.06 });
  }

  arp(time, freq, gain) {
    this.tone(time, freq, 0.08, { type: "triangle", gain, release: 0.08 });
    this.tone(time, freq * 2.005, 0.06, { type: "sine", gain: gain * 0.4, release: 0.06, dest: this.delay });
  }

  pad(time, root, chord, dur) {
    chord.slice(0, 3).forEach((semi, i) => {
      const freq = root * Math.pow(2, semi / 12) * 2;
      this.tone(time, freq, dur, {
        type: i === 0 ? "triangle" : "sawtooth",
        gain: 0.035,
        attack: 0.6,
        release: 1.2,
        filter: "lowpass",
        filterQ: 0.8,
        detune: (i - 1) * 7,
      });
    });
  }

  sparkle(time) {
    [0, 4, 7, 11, 14].forEach((semi, i) => {
      this.tone(time + i * 0.055, midiToFreq(81 + semi), 0.16, {
        type: "sine",
        gain: 0.05,
        release: 0.4,
        dest: this.delay,
      });
    });
  }

  duck(time) {
    if (!this.music) return;
    this.music.gain.cancelScheduledValues(time);
    this.music.gain.setValueAtTime(0.5, time);
    this.music.gain.linearRampToValueAtTime(0.2, time + 0.03);
    this.music.gain.linearRampToValueAtTime(0.5, time + 0.22);
  }

  sfxCreate() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime + 0.02;
    const notes = [0, 4, 7, 11, 14, 19, 23, 26];
    notes.forEach((semi, i) => {
      this.tone(t + i * 0.06, midiToFreq(72 + semi), 0.18, {
        type: i % 2 ? "triangle" : "sine",
        gain: 0.11,
        release: 0.5,
        dest: this.sfx,
      });
    });
    this.noise(t, 0.7, { gain: 0.1, type: "highpass", freq: 3000, slideTo: 12000, dest: this.sfx });
    this.tone(t, 220, 0.6, { type: "sine", gain: 0.1, slideTo: 880, dest: this.sfx });
  }

  sfxDestroy() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime + 0.02;
    this.tone(t, 130, 1.1, { type: "sine", gain: 0.65, slideTo: 28, release: 0.4, dest: this.sfx });
    this.tone(t, 84, 0.7, { type: "square", gain: 0.12, slideTo: 40, filter: "lowpass", filterQ: 2, dest: this.sfx });
    this.noise(t, 1.2, { gain: 0.45, type: "lowpass", freq: 5000, slideTo: 90, dest: this.sfx });
    this.noise(t, 0.25, { gain: 0.3, type: "highpass", freq: 400, dest: this.sfx });
    if (this.distortion) {
      const shaper = this.ctx.createWaveShaper();
      shaper.curve = this.distortion;
      shaper.oversample = "2x";
      const src = this.ctx.createBufferSource();
      src.buffer = this.noiseBuffer;
      const g = this.ctx.createGain();
      g.gain.value = 0.16;
      src.connect(shaper).connect(g).connect(this.sfx);
      src.start(t);
      src.stop(t + 0.6);
    }
  }

  sfxChange() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime + 0.02;
    this.tone(t, 180, 0.65, {
      type: "sawtooth",
      gain: 0.12,
      slideTo: 1600,
      filter: "bandpass",
      filterQ: 3,
      release: 0.2,
      dest: this.sfx,
    });
    [0, 7, 12, 19].forEach((semi, i) => {
      this.tone(t + 0.5 + i * 0.045, midiToFreq(72 + semi), 0.22, {
        type: "triangle",
        gain: 0.09,
        release: 0.5,
        dest: this.sfx,
      });
    });
  }

  sfxBless() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime + 0.01;
    this.tone(t, 1046.5, 0.5, { type: "sine", gain: 0.09, release: 1.4, dest: this.sfx });
    this.tone(t + 0.08, 1568, 0.4, { type: "sine", gain: 0.06, release: 1.2, dest: this.sfx });
    this.tone(t + 0.16, 2093, 0.3, { type: "triangle", gain: 0.03, release: 1.0, dest: this.sfx });
    this.noise(t, 0.5, { gain: 0.04, type: "highpass", freq: 9000, dest: this.sfx });
  }

  sfxUi() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime + 0.005;
    this.tone(t, 720, 0.05, { type: "sine", gain: 0.04, release: 0.06, dest: this.sfx });
  }
}

import * as THREE from "three";

let glowTexture = null;

export function getGlowTexture() {
  if (glowTexture) return glowTexture;
  const size = 256;
  const canvas = document.createElement("canvas");
  canvas.width = canvas.height = size;
  const ctx = canvas.getContext("2d");
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  g.addColorStop(0, "rgba(255,255,255,1)");
  g.addColorStop(0.12, "rgba(255,255,255,0.92)");
  g.addColorStop(0.35, "rgba(255,255,255,0.32)");
  g.addColorStop(0.68, "rgba(255,255,255,0.06)");
  g.addColorStop(1, "rgba(255,255,255,0)");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  glowTexture = new THREE.CanvasTexture(canvas);
  glowTexture.colorSpace = THREE.SRGBColorSpace;
  glowTexture.needsUpdate = true;
  return glowTexture;
}

export function makeGlowSprite(color, scale = 1, opacity = 1) {
  const material = new THREE.SpriteMaterial({
    map: getGlowTexture(),
    color,
    transparent: true,
    opacity,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
    toneMapped: false,
  });
  const sprite = new THREE.Sprite(material);
  sprite.scale.set(scale, scale, 1);
  return sprite;
}

export function lerpColor(uniformOrColor, target, k) {
  if (uniformOrColor && uniformOrColor.value && uniformOrColor.value.isColor) {
    uniformOrColor.value.lerp(target, k);
  } else if (uniformOrColor && uniformOrColor.isColor) {
    uniformOrColor.lerp(target, k);
  }
}

export function damp(current, target, lambda, dt) {
  return current + (target - current) * (1 - Math.exp(-lambda * dt));
}

export function rand(min, max) {
  return min + Math.random() * (max - min);
}

export function easeOutCubic(x) {
  return 1 - Math.pow(1 - x, 3);
}

export function easeInOutCubic(x) {
  return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
}

import * as THREE from "three";
import { makeGlowSprite, rand } from "./utils.js";

const skyVertex = /* glsl */ `
  varying vec3 vPos;
  void main() {
    vPos = position;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;

const skyFragment = /* glsl */ `
  uniform vec3 uTop;
  uniform vec3 uMid;
  uniform vec3 uAccent;
  uniform float uTime;
  varying vec3 vPos;

  float hash(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
  }

  void main() {
    vec3 d = normalize(vPos);
    float h = clamp(d.y * 0.5 + 0.5, 0.0, 1.0);

    vec3 col = mix(uTop, vec3(0.012, 0.002, 0.03), smoothstep(0.0, 0.55, h));
    col = mix(col, uMid, pow(h, 3.4) * 0.82);

    float horizon = exp(-abs(d.y) * 5.0);
    col += uMid * horizon * 0.42;

    float a = sin(d.x * 5.0 + uTime * 0.16 + sin(d.z * 4.0 - uTime * 0.13) * 2.2);
    a = pow(max(0.0, a), 5.0);
    float b = sin(d.z * 7.0 - uTime * 0.21 + sin(d.x * 3.0 + uTime * 0.1) * 2.6);
    b = pow(max(0.0, b), 7.0);
    float aurora = smoothstep(-0.15, 0.7, d.y);
    col += uAccent * (a * 0.30 + b * 0.22) * aurora;

    float back = pow(max(0.0, -d.z), 7.0) * smoothstep(-0.25, 0.85, d.y);
    col += uMid * back * 0.55;

    float lowGlow = pow(max(0.0, -d.y), 2.0) * 0.12;
    col += uMid * lowGlow;

    col += (hash(gl_FragCoord.xy + uTime) - 0.5) * 0.012;
    gl_FragColor = vec4(col, 1.0);
  }
`;

const floorVertex = /* glsl */ `
  varying vec3 vWorld;
  varying vec2 vUv;
  void main() {
    vUv = uv;
    vec4 world = modelMatrix * vec4(position, 1.0);
    vWorld = world.xyz;
    gl_Position = projectionMatrix * viewMatrix * world;
  }
`;

const floorFragment = /* glsl */ `
  uniform vec3 uBase;
  uniform vec3 uGrid;
  uniform vec3 uRing;
  uniform vec3 uAccent;
  uniform float uTime;
  varying vec3 vWorld;
  varying vec2 vUv;

  float grid(vec2 p, float scale, float width) {
    vec2 q = p * scale;
    vec2 g = abs(fract(q - 0.5) - 0.5) / fwidth(q);
    return 1.0 - min(min(g.x, g.y) / width, 1.0);
  }

  void main() {
    vec2 p = vWorld.xz;
    float r = length(p);

    vec3 col = uBase;
    float glow = exp(-r * 0.9);
    col += uRing * glow * 0.18;
    col += uRing * exp(-r * 2.7) * 0.30;

    float fade = 1.0 - smoothstep(2.0, 17.0, r);
    float g1 = grid(p, 1.0, 1.15);
    float g2 = grid(p, 0.25, 0.9);
    col += uGrid * (g1 * 0.42 + g2 * 0.10) * fade;

    float rings = smoothstep(0.9, 1.0, sin(r * 6.2 - uTime * 1.4) * 0.5 + 0.5);
    col += uAccent * rings * exp(-r * 0.24) * 0.28;

    float streak = exp(-abs(p.x) * 3.2) * smoothstep(-3.0, 7.0, p.y) * exp(-abs(p.y - 1.4) * 0.32);
    col += uAccent * streak * 0.10;

    float scan = sin(p.y * 24.0 - uTime * 2.2) * 0.5 + 0.5;
    col *= 0.94 + scan * 0.06 * exp(-r * 0.2);

    float alpha = 1.0 - smoothstep(13.0, 27.0, r);
    gl_FragColor = vec4(col, alpha * 0.97);
  }
`;

const ringVertex = /* glsl */ `
  varying vec2 vUv;
  void main() {
    vUv = uv;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;

const ringFragment = /* glsl */ `
  uniform vec3 uColorA;
  uniform vec3 uColorB;
  uniform float uTime;
  uniform float uOpacity;
  varying vec2 vUv;
  void main() {
    float dash = smoothstep(0.18, 0.72, sin(vUv.x * 6.28318 * 18.0 + uTime * 0.7) * 0.5 + 0.5);
    vec3 col = mix(uColorA, uColorB, vUv.x * 4.0);
    col += vec3(0.5) * pow(dash, 8.0);
    gl_FragColor = vec4(col, (0.24 + dash * 0.76) * uOpacity);
  }
`;

const beamVertex = /* glsl */ `
  varying vec2 vUv;
  void main() {
    vUv = uv;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;

const beamFragment = /* glsl */ `
  uniform vec3 uColor;
  uniform float uOpacity;
  varying vec2 vUv;
  void main() {
    float edge = smoothstep(0.0, 0.32, vUv.x) * smoothstep(1.0, 0.68, vUv.x);
    float vert = smoothstep(0.0, 0.22, vUv.y) * pow(1.0 - vUv.y, 1.6);
    gl_FragColor = vec4(uColor, edge * vert * uOpacity);
  }
`;

const pillarFragment = /* glsl */ `
  uniform vec3 uColor;
  uniform float uTime;
  uniform float uOpacity;
  varying vec2 vUv;
  void main() {
    float vert = pow(1.0 - vUv.y, 2.2);
    float stripe = 0.65 + 0.35 * sin(vUv.x * 6.28318 * 16.0 + uTime * 0.9);
    float edge = smoothstep(0.0, 0.2, vUv.x) * smoothstep(1.0, 0.8, vUv.x);
    gl_FragColor = vec4(uColor, vert * stripe * edge * uOpacity);
  }
`;

function energyRing(radius, tube, colorA, colorB, opacity, segments = 220) {
  const material = new THREE.ShaderMaterial({
    uniforms: {
      uColorA: { value: new THREE.Color(colorA) },
      uColorB: { value: new THREE.Color(colorB) },
      uTime: { value: 0 },
      uOpacity: { value: opacity },
    },
    vertexShader: ringVertex,
    fragmentShader: ringFragment,
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    side: THREE.DoubleSide,
    toneMapped: false,
  });
  const mesh = new THREE.Mesh(new THREE.TorusGeometry(radius, tube, 8, segments), material);
  mesh.rotation.x = -Math.PI / 2;
  return mesh;
}

export function createEnvironment(scene, palette) {
  const group = new THREE.Group();
  scene.add(group);

  const target = {
    skyTop: new THREE.Color(palette.skyTop),
    skyMid: new THREE.Color(palette.skyMid),
    skyAccent: new THREE.Color(palette.skyAccent),
    floorBase: new THREE.Color(palette.floorBase),
    floorGrid: new THREE.Color(palette.floorGrid),
    floorRing: new THREE.Color(palette.floorRing),
    floorAccent: new THREE.Color(palette.floorAccent),
    fog: new THREE.Color(palette.fog),
    lightA: new THREE.Color(palette.lightA),
    lightB: new THREE.Color(palette.lightB),
    ringA: new THREE.Color(palette.skyMid),
    ringB: new THREE.Color(palette.skyAccent),
    beam: new THREE.Color(palette.skyMid),
    pillar: new THREE.Color(palette.skyAccent),
    bubble: new THREE.Color(0xffffff),
  };

  const skyUniforms = {
    uTop: { value: target.skyTop.clone() },
    uMid: { value: target.skyMid.clone() },
    uAccent: { value: target.skyAccent.clone() },
    uTime: { value: 0 },
  };
  const sky = new THREE.Mesh(
    new THREE.SphereGeometry(80, 48, 32),
    new THREE.ShaderMaterial({
      uniforms: skyUniforms,
      vertexShader: skyVertex,
      fragmentShader: skyFragment,
      side: THREE.BackSide,
      depthWrite: false,
      fog: false,
      toneMapped: false,
    })
  );
  sky.renderOrder = -10;
  group.add(sky);

  const floorUniforms = {
    uBase: { value: target.floorBase.clone() },
    uGrid: { value: target.floorGrid.clone() },
    uRing: { value: target.floorRing.clone() },
    uAccent: { value: target.floorAccent.clone() },
    uTime: { value: 0 },
  };
  const floor = new THREE.Mesh(
    new THREE.CircleGeometry(30, 120),
    new THREE.ShaderMaterial({
      uniforms: floorUniforms,
      vertexShader: floorVertex,
      fragmentShader: floorFragment,
      transparent: true,
      depthWrite: false,
      toneMapped: false,
    })
  );
  floor.rotation.x = -Math.PI / 2;
  floor.position.y = -1.62;
  floor.renderOrder = -2;
  group.add(floor);

  scene.fog = new THREE.FogExp2(target.fog.clone().getHex(), 0.018);

  // stars
  const starCount = 1100;
  const starPos = new Float32Array(starCount * 3);
  const starCol = new Float32Array(starCount * 3);
  const starColors = [new THREE.Color(0xffffff), new THREE.Color(0xffb7f2), new THREE.Color(0xa8f6ff), new THREE.Color(0xfff0b0)];
  for (let i = 0; i < starCount; i++) {
    const r = rand(26, 58);
    const theta = rand(0, Math.PI * 2);
    const phi = Math.acos(rand(-0.4, 1));
    starPos[i * 3] = Math.sin(phi) * Math.cos(theta) * r;
    starPos[i * 3 + 1] = Math.cos(phi) * r * 0.9 + 4;
    starPos[i * 3 + 2] = Math.sin(phi) * Math.sin(theta) * r;
    const c = starColors[Math.floor(Math.random() * starColors.length)];
    const bright = rand(0.35, 1);
    starCol[i * 3] = c.r * bright;
    starCol[i * 3 + 1] = c.g * bright;
    starCol[i * 3 + 2] = c.b * bright;
  }
  const starGeo = new THREE.BufferGeometry();
  starGeo.setAttribute("position", new THREE.BufferAttribute(starPos, 3));
  starGeo.setAttribute("color", new THREE.BufferAttribute(starCol, 3));
  const stars = new THREE.Points(
    starGeo,
    new THREE.PointsMaterial({
      size: 0.11,
      sizeAttenuation: true,
      vertexColors: true,
      transparent: true,
      opacity: 0.85,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      toneMapped: false,
    })
  );
  group.add(stars);

  // altar
  const altar = new THREE.Group();
  group.add(altar);

  const chrome = new THREE.MeshPhysicalMaterial({
    color: 0xdfe4ff,
    metalness: 1,
    roughness: 0.09,
    clearcoat: 1,
    clearcoatRoughness: 0.05,
    iridescence: 0.75,
    iridescenceIOR: 1.35,
    iridescenceThicknessRange: [100, 620],
    envMapIntensity: 1.5,
  });
  const darkChrome = new THREE.MeshPhysicalMaterial({
    color: 0x3a2352,
    metalness: 1,
    roughness: 0.05,
    clearcoat: 1,
    envMapIntensity: 1.4,
  });

  const base = new THREE.Mesh(new THREE.CylinderGeometry(1.36, 1.5, 0.2, 96), chrome);
  base.position.y = -1.5;
  altar.add(base);

  const top = new THREE.Mesh(new THREE.CircleGeometry(1.34, 96), darkChrome);
  top.rotation.x = -Math.PI / 2;
  top.position.y = -1.397;
  altar.add(top);

  const bevel = new THREE.Mesh(new THREE.TorusGeometry(1.36, 0.035, 12, 120), chrome);
  bevel.rotation.x = -Math.PI / 2;
  bevel.position.y = -1.4;
  altar.add(bevel);

  const underGlow = makeGlowSprite(palette.skyAccent, 5.2, 0.55);
  underGlow.position.y = -1.55;
  underGlow.material.toneMapped = false;
  altar.add(underGlow);

  const rimMaterial = new THREE.MeshBasicMaterial({
    color: palette.skyAccent,
    transparent: true,
    opacity: 0.9,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
    toneMapped: false,
  });
  const rim = new THREE.Mesh(new THREE.TorusGeometry(1.33, 0.01, 6, 140), rimMaterial);
  rim.rotation.x = -Math.PI / 2;
  rim.position.y = -1.393;
  altar.add(rim);

  const runeGroup = new THREE.Group();
  runeGroup.position.y = -1.39;
  altar.add(runeGroup);
  const runeMaterial = new THREE.MeshBasicMaterial({
    color: palette.skyMid,
    transparent: true,
    opacity: 0.8,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
    toneMapped: false,
  });
  const runeGeo = new THREE.BoxGeometry(0.035, 0.008, 0.16);
  for (let i = 0; i < 32; i++) {
    const a = (i / 32) * Math.PI * 2;
    const rune = new THREE.Mesh(runeGeo, runeMaterial);
    rune.position.set(Math.cos(a) * 1.2, 0, Math.sin(a) * 1.2);
    rune.rotation.y = -a;
    rune.scale.z = i % 4 === 0 ? 1.5 : 0.7;
    runeGroup.add(rune);
  }

  const ringA = energyRing(1.46, 0.008, palette.skyMid, palette.skyAccent, 0.8, 160);
  ringA.position.y = -1.38;
  altar.add(ringA);
  const ringB = energyRing(1.82, 0.006, palette.skyAccent, palette.skyMid, 0.5, 180);
  ringB.position.y = -1.36;
  altar.add(ringB);

  const orbitRings = [];
  [
    [2.25, 0.004, 0.34, 0.22],
    [2.85, 0.0035, 0.22, -0.16],
    [3.7, 0.003, 0.13, 0.12],
  ].forEach(([radius, tube, opacity, tilt], i) => {
    const holder = new THREE.Group();
    holder.position.y = -1.34;
    holder.rotation.x = tilt;
    const r = energyRing(radius, tube, palette.skyMid, palette.skyAccent, opacity, 240);
    holder.add(r);
    holder.userData.spin = 0.05 + i * 0.035;
    group.add(holder);
    orbitRings.push(holder);
  });

  // light pillar
  const pillarUniforms = {
    uColor: { value: target.pillar.clone() },
    uTime: { value: 0 },
    uOpacity: { value: 0.075 },
  };
  const pillar = new THREE.Mesh(
    new THREE.CylinderGeometry(1.05, 1.45, 6.4, 64, 1, true),
    new THREE.ShaderMaterial({
      uniforms: pillarUniforms,
      vertexShader: beamVertex,
      fragmentShader: pillarFragment,
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      side: THREE.DoubleSide,
      toneMapped: false,
    })
  );
  pillar.position.y = 1.55;
  group.add(pillar);

  // god rays
  const beams = [];
  for (let i = 0; i < 5; i++) {
    const uniforms = {
      uColor: { value: target.beam.clone() },
      uOpacity: { value: 0.09 },
    };
    const beam = new THREE.Mesh(
      new THREE.PlaneGeometry(rand(0.8, 1.8), rand(10, 14)),
      new THREE.ShaderMaterial({
        uniforms,
        vertexShader: beamVertex,
        fragmentShader: beamFragment,
        transparent: true,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
        side: THREE.DoubleSide,
        toneMapped: false,
      })
    );
    beam.position.set(rand(-6, 6), rand(3, 5), rand(-6, -2.5));
    beam.rotation.z = rand(-0.4, 0.4);
    beam.rotation.y = rand(-0.4, 0.4);
    beam.renderOrder = -1;
    group.add(beam);
    beams.push(beam);
  }

  // floating chrome bubbles
  const bubbleCount = 24;
  const bubbleGeo = new THREE.IcosahedronGeometry(1, 2);
  const bubbleMat = new THREE.MeshPhysicalMaterial({
    color: 0xffffff,
    metalness: 1,
    roughness: 0.06,
    clearcoat: 1,
    iridescence: 1,
    iridescenceIOR: 1.5,
    envMapIntensity: 1.6,
  });
  const bubbles = new THREE.InstancedMesh(bubbleGeo, bubbleMat, bubbleCount);
  bubbles.frustumCulled = false;
  const bubbleData = [];
  const dummy = new THREE.Object3D();
  for (let i = 0; i < bubbleCount; i++) {
    const big = i < 4;
    const angle = rand(0, Math.PI * 2);
    const radius = big ? rand(6, 9) : rand(3.4, 9);
    const scale = big ? rand(0.7, 1.25) : rand(0.08, 0.42);
    const data = {
      base: new THREE.Vector3(Math.cos(angle) * radius, rand(-0.8, 5.5), Math.sin(angle) * radius - 1.2),
      scale,
      phase: rand(0, Math.PI * 2),
      speed: rand(0.12, 0.4),
      spin: new THREE.Vector3(rand(-0.2, 0.2), rand(-0.2, 0.2), rand(-0.2, 0.2)),
      rotation: new THREE.Euler(rand(0, 6), rand(0, 6), rand(0, 6)),
    };
    bubbleData.push(data);
    dummy.position.copy(data.base);
    dummy.scale.setScalar(scale);
    dummy.updateMatrix();
    bubbles.setMatrixAt(i, dummy.matrix);
  }
  group.add(bubbles);

  // dust
  const dustCount = 420;
  const dustPos = new Float32Array(dustCount * 3);
  for (let i = 0; i < dustCount; i++) {
    const a = rand(0, Math.PI * 2);
    const r = Math.sqrt(Math.random()) * 9;
    dustPos[i * 3] = Math.cos(a) * r;
    dustPos[i * 3 + 1] = rand(-1.4, 6);
    dustPos[i * 3 + 2] = Math.sin(a) * r;
  }
  const dustGeo = new THREE.BufferGeometry();
  dustGeo.setAttribute("position", new THREE.BufferAttribute(dustPos, 3));
  const dust = new THREE.Points(
    dustGeo,
    new THREE.PointsMaterial({
      color: 0xffe8ff,
      size: 0.035,
      sizeAttenuation: true,
      transparent: true,
      opacity: 0.45,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      toneMapped: false,
    })
  );
  group.add(dust);

  const current = {
    skyTop: target.skyTop.clone(),
    skyMid: target.skyMid.clone(),
    skyAccent: target.skyAccent.clone(),
    floorBase: target.floorBase.clone(),
    floorGrid: target.floorGrid.clone(),
    floorRing: target.floorRing.clone(),
    floorAccent: target.floorAccent.clone(),
    fog: target.fog.clone(),
    ringA: target.ringA.clone(),
    ringB: target.ringB.clone(),
    beam: target.beam.clone(),
    pillar: target.pillar.clone(),
  };

  function setPalette(p, instant = false) {
    target.skyTop.set(p.skyTop);
    target.skyMid.set(p.skyMid);
    target.skyAccent.set(p.skyAccent);
    target.floorBase.set(p.floorBase);
    target.floorGrid.set(p.floorGrid);
    target.floorRing.set(p.floorRing);
    target.floorAccent.set(p.floorAccent);
    target.fog.set(p.fog);
    target.lightA.set(p.lightA);
    target.lightB.set(p.lightB);
    target.ringA.set(p.skyMid);
    target.ringB.set(p.skyAccent);
    target.beam.set(p.skyMid);
    target.pillar.set(p.skyAccent);

    underGlow.material.color.set(p.skyAccent);
    rimMaterial.color.set(p.skyAccent);
    runeMaterial.color.set(p.skyMid);

    if (instant) {
      current.skyTop.copy(target.skyTop);
      current.skyMid.copy(target.skyMid);
      current.skyAccent.copy(target.skyAccent);
      current.floorBase.copy(target.floorBase);
      current.floorGrid.copy(target.floorGrid);
      current.floorRing.copy(target.floorRing);
      current.floorAccent.copy(target.floorAccent);
      current.fog.copy(target.fog);
      current.ringA.copy(target.ringA);
      current.ringB.copy(target.ringB);
      current.beam.copy(target.beam);
      current.pillar.copy(target.pillar);
      scene.fog.color.copy(current.fog);
    }
  }

  let time = 0;
  function update(dt, elapsed) {
    time = elapsed;
    const k = 1 - Math.exp(-2.2 * dt);
    current.skyTop.lerp(target.skyTop, k);
    current.skyMid.lerp(target.skyMid, k);
    current.skyAccent.lerp(target.skyAccent, k);
    current.floorBase.lerp(target.floorBase, k);
    current.floorGrid.lerp(target.floorGrid, k);
    current.floorRing.lerp(target.floorRing, k);
    current.floorAccent.lerp(target.floorAccent, k);
    current.fog.lerp(target.fog, k);
    current.ringA.lerp(target.ringA, k);
    current.ringB.lerp(target.ringB, k);
    current.beam.lerp(target.beam, k);
    current.pillar.lerp(target.pillar, k);

    skyUniforms.uTop.value.copy(current.skyTop);
    skyUniforms.uMid.value.copy(current.skyMid);
    skyUniforms.uAccent.value.copy(current.skyAccent);
    skyUniforms.uTime.value = time;

    floorUniforms.uBase.value.copy(current.floorBase);
    floorUniforms.uGrid.value.copy(current.floorGrid);
    floorUniforms.uRing.value.copy(current.floorRing);
    floorUniforms.uAccent.value.copy(current.floorAccent);
    floorUniforms.uTime.value = time;

    scene.fog.color.copy(current.fog);
    pillarUniforms.uColor.value.copy(current.pillar);
    pillarUniforms.uTime.value = time;

    ringA.material.uniforms.uColorA.value.copy(current.ringA);
    ringA.material.uniforms.uColorB.value.copy(current.ringB);
    ringB.material.uniforms.uColorA.value.copy(current.ringB);
    ringB.material.uniforms.uColorB.value.copy(current.ringA);
    ringA.material.uniforms.uTime.value = time;
    ringB.material.uniforms.uTime.value = time;

    orbitRings.forEach((holder, i) => {
      holder.rotation.z += dt * holder.userData.spin * (i % 2 ? -1 : 1);
      holder.rotation.x += Math.sin(time * 0.2 + i) * dt * 0.01;
      holder.children[0].material.uniforms.uTime.value = time;
      holder.children[0].material.uniforms.uColorA.value.copy(current.ringA);
      holder.children[0].material.uniforms.uColorB.value.copy(current.ringB);
    });

    beams.forEach((beam, i) => {
      beam.material.uniforms.uColor.value.copy(current.beam);
      beam.material.uniforms.uOpacity.value = 0.055 + Math.sin(time * 0.35 + i) * 0.02;
      beam.rotation.z += Math.sin(time * 0.12 + i) * dt * 0.01;
    });

    stars.rotation.y += dt * 0.004;
    stars.material.opacity = 0.72 + Math.sin(time * 0.8) * 0.1;
    dust.rotation.y += dt * 0.012;
    dust.position.y = Math.sin(time * 0.4) * 0.08;

    for (let i = 0; i < bubbleCount; i++) {
      const d = bubbleData[i];
      dummy.position.set(
        d.base.x + Math.sin(time * d.speed + d.phase) * 0.35,
        d.base.y + Math.sin(time * d.speed * 1.4 + d.phase) * 0.32,
        d.base.z + Math.cos(time * d.speed * 0.8 + d.phase) * 0.35
      );
      d.rotation.x += d.spin.x * dt;
      d.rotation.y += d.spin.y * dt;
      d.rotation.z += d.spin.z * dt;
      dummy.rotation.copy(d.rotation);
      dummy.scale.setScalar(d.scale * (1 + Math.sin(time * 0.7 + d.phase) * 0.04));
      dummy.updateMatrix();
      bubbles.setMatrixAt(i, dummy.matrix);
    }
    bubbles.instanceMatrix.needsUpdate = true;

    underGlow.material.opacity = 0.42 + Math.sin(time * 1.6) * 0.1;
    rimMaterial.opacity = 0.65 + Math.sin(time * 2.1) * 0.25;
    runeGroup.rotation.y -= dt * 0.18;
    ringA.rotation.z += dt * 0.1;
    ringB.rotation.z -= dt * 0.08;
  }

  return {
    group,
    setPalette,
    update,
    materials: { chrome, darkChrome, bubbleMat, rimMaterial, runeMaterial },
    underGlow,
  };
}

import * as THREE from "three";
import { makeGlowSprite, rand } from "./utils.js";

const hairVertex = /* glsl */ `
  uniform float uTime;
  varying vec2 vUv;
  varying vec3 vNormalView;
  varying vec3 vViewDir;
  void main() {
    vUv = uv;
    vec3 p = position;
    float sway = sin(uv.y * 6.5 + uTime * 1.35 + position.x * 2.0) * (0.02 + uv.y * 0.085);
    p.x += sway;
    p.z += cos(uv.y * 4.8 + uTime * 1.05 + position.y * 1.5) * 0.022 * uv.y;
    vec4 mv = modelViewMatrix * vec4(p, 1.0);
    vNormalView = normalize(normalMatrix * normal);
    vViewDir = normalize(-mv.xyz);
    gl_Position = projectionMatrix * mv;
  }
`;

const hairFragment = /* glsl */ `
  uniform vec3 uColorA;
  uniform vec3 uColorB;
  uniform vec3 uColorC;
  uniform float uOpacity;
  varying vec2 vUv;
  varying vec3 vNormalView;
  varying vec3 vViewDir;
  void main() {
    vec3 col = mix(uColorA, uColorB, smoothstep(0.0, 1.0, vUv.y));
    float edge = pow(1.0 - abs(dot(normalize(vNormalView), normalize(vViewDir))), 1.5);
    col += uColorC * edge * 0.75;
    float alpha = uOpacity * smoothstep(0.0, 0.08, vUv.y) * (0.45 + edge * 0.55);
    gl_FragColor = vec4(col, alpha);
  }
`;

const clothVertex = /* glsl */ `
  uniform float uTime;
  varying vec2 vUv;
  varying vec3 vNormalView;
  varying vec3 vViewDir;
  void main() {
    vUv = uv;
    vec3 p = position;
    float wave = sin(uv.y * 7.0 + uTime * 1.15) * 0.045 + cos(uv.x * 9.0 - uTime * 0.9) * 0.028;
    p.x += wave * uv.y;
    p.z += cos(uv.y * 5.0 + uTime * 0.8) * 0.035 * uv.y;
    vec4 mv = modelViewMatrix * vec4(p, 1.0);
    vNormalView = normalize(normalMatrix * normal);
    vViewDir = normalize(-mv.xyz);
    gl_Position = projectionMatrix * mv;
  }
`;

const clothFragment = /* glsl */ `
  uniform vec3 uColorA;
  uniform vec3 uColorB;
  uniform vec3 uColorC;
  uniform float uOpacity;
  uniform float uTime;
  varying vec2 vUv;
  varying vec3 vNormalView;
  varying vec3 vViewDir;
  void main() {
    float fres = pow(1.0 - abs(dot(normalize(vNormalView), normalize(vViewDir))), 2.0);
    float stripe = pow(sin(vUv.y * 95.0 - uTime * 2.2) * 0.5 + 0.5, 9.0);
    float flow = sin(vUv.x * 6.28318 * 3.0 + uTime * 0.7 + vUv.y * 5.0) * 0.5 + 0.5;
    vec3 col = mix(uColorA, uColorB, clamp(vUv.y * 1.25 + flow * 0.16, 0.0, 1.0));
    col += uColorC * (fres * 0.85 + stripe * 0.35 + flow * 0.12);
    float alpha = (0.055 + fres * 0.62 + stripe * 0.06) * smoothstep(0.0, 0.1, vUv.y);
    alpha *= 1.0 - smoothstep(0.72, 1.0, vUv.y) * 0.82;
    gl_FragColor = vec4(col, alpha * uOpacity);
  }
`;

const capeFragment = /* glsl */ `
  uniform vec3 uColorA;
  uniform vec3 uColorB;
  uniform vec3 uColorC;
  uniform float uOpacity;
  uniform float uTime;
  varying vec2 vUv;
  varying vec3 vNormalView;
  varying vec3 vViewDir;
  void main() {
    float fres = pow(1.0 - abs(dot(normalize(vNormalView), normalize(vViewDir))), 2.0);
    vec3 col = mix(uColorB, uColorA, smoothstep(0.0, 1.0, vUv.y));
    col += uColorC * fres * 0.7;
    float edge = smoothstep(0.0, 0.16, vUv.x) * smoothstep(1.0, 0.84, vUv.x);
    float alpha = (0.06 + fres * 0.5) * edge * smoothstep(0.0, 0.12, vUv.y);
    alpha *= 1.0 - smoothstep(0.6, 1.0, vUv.y) * 0.9;
    float shimmer = pow(sin(vUv.y * 60.0 - uTime * 2.6 + vUv.x * 20.0) * 0.5 + 0.5, 10.0);
    col += uColorC * shimmer * 0.3;
    gl_FragColor = vec4(col, alpha * uOpacity);
  }
`;

const haloVertex = /* glsl */ `
  varying vec2 vUv;
  void main() {
    vUv = uv;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;

const haloFragment = /* glsl */ `
  uniform vec3 uColorA;
  uniform vec3 uColorB;
  uniform float uTime;
  uniform float uOpacity;
  varying vec2 vUv;
  void main() {
    float dash = pow(sin(vUv.x * 6.28318 * 14.0 + uTime * 1.3) * 0.5 + 0.5, 4.0);
    vec3 col = mix(uColorA, uColorB, vUv.x * 3.0);
    col += vec3(0.4) * dash;
    gl_FragColor = vec4(col, (0.35 + dash * 0.65) * uOpacity);
  }
`;

function ribbonGeometry(points, width, segments = 42) {
  const curve = new THREE.CatmullRomCurve3(points.map((p) => new THREE.Vector3(...p)));
  const positions = [];
  const normals = [];
  const uvs = [];
  const indices = [];
  const tangent = new THREE.Vector3();
  const side = new THREE.Vector3();
  const normal = new THREE.Vector3();
  const reference = new THREE.Vector3(0, 0, 1);

  for (let i = 0; i <= segments; i++) {
    const t = i / segments;
    const p = curve.getPoint(t);
    curve.getTangent(t, tangent).normalize();
    side.crossVectors(tangent, reference);
    if (side.lengthSq() < 0.001) side.set(1, 0, 0);
    side.normalize();
    normal.crossVectors(tangent, side).normalize();
    const w = width * (1 - t * 0.72) * (0.72 + 0.28 * Math.sin(t * Math.PI));
    positions.push(p.x - side.x * w, p.y - side.y * w, p.z - side.z * w);
    positions.push(p.x + side.x * w, p.y + side.y * w, p.z + side.z * w);
    normals.push(normal.x, normal.y, normal.z, normal.x, normal.y, normal.z);
    uvs.push(0, t, 1, t);
    if (i < segments) {
      const a = i * 2;
      indices.push(a, a + 1, a + 2, a + 1, a + 3, a + 2);
    }
  }

  const geo = new THREE.BufferGeometry();
  geo.setAttribute("position", new THREE.Float32BufferAttribute(positions, 3));
  geo.setAttribute("normal", new THREE.Float32BufferAttribute(normals, 3));
  geo.setAttribute("uv", new THREE.Float32BufferAttribute(uvs, 2));
  geo.setIndex(indices);
  return geo;
}

function makeHaloMaterial(colorA, colorB, opacity) {
  return new THREE.ShaderMaterial({
    uniforms: {
      uColorA: { value: new THREE.Color(colorA) },
      uColorB: { value: new THREE.Color(colorB) },
      uTime: { value: 0 },
      uOpacity: { value: opacity },
    },
    vertexShader: haloVertex,
    fragmentShader: haloFragment,
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    side: THREE.DoubleSide,
    toneMapped: false,
  });
}

export function createGoddess(palette) {
  const root = new THREE.Group();
  root.position.y = 0.14;
  const body = new THREE.Group();
  root.add(body);

  const chrome = new THREE.MeshPhysicalMaterial({
    color: 0xf4f2ff,
    metalness: 1,
    roughness: 0.1,
    clearcoat: 1,
    clearcoatRoughness: 0.05,
    iridescence: 1,
    iridescenceIOR: 1.5,
    iridescenceThicknessRange: [80, 700],
    envMapIntensity: 1.75,
  });
  const darkGlass = new THREE.MeshPhysicalMaterial({
    color: 0x1a0726,
    metalness: 0.9,
    roughness: 0.05,
    clearcoat: 1,
    clearcoatRoughness: 0.03,
    iridescence: 1,
    iridescenceIOR: 1.7,
    iridescenceThicknessRange: [200, 900],
    envMapIntensity: 1.8,
  });

  const target = {
    hairA: new THREE.Color(palette.hairA),
    hairB: new THREE.Color(palette.hairB),
    hairC: new THREE.Color(palette.hairC),
    dressA: new THREE.Color(palette.dressA),
    dressB: new THREE.Color(palette.dressB),
    dressC: new THREE.Color(palette.dressC),
    heart: new THREE.Color(palette.heart),
    haloA: new THREE.Color(palette.halo),
    haloB: new THREE.Color(palette.skyAccent),
    eye: new THREE.Color(palette.eye),
    gemA: new THREE.Color(palette.skyMid),
    gemB: new THREE.Color(palette.skyAccent),
    gemC: new THREE.Color(0xfff4ff),
  };

  const current = {
    hairA: target.hairA.clone(),
    hairB: target.hairB.clone(),
    hairC: target.hairC.clone(),
    dressA: target.dressA.clone(),
    dressB: target.dressB.clone(),
    dressC: target.dressC.clone(),
    heart: target.heart.clone(),
    haloA: target.haloA.clone(),
    haloB: target.haloB.clone(),
    eye: target.eye.clone(),
    gemA: target.gemA.clone(),
    gemB: target.gemB.clone(),
    gemC: target.gemC.clone(),
  };

  // torso
  const torsoProfile = new THREE.SplineCurve([
    new THREE.Vector2(0.001, -0.72),
    new THREE.Vector2(0.18, -0.71),
    new THREE.Vector2(0.34, -0.68),
    new THREE.Vector2(0.46, -0.61),
    new THREE.Vector2(0.51, -0.5),
    new THREE.Vector2(0.49, -0.38),
    new THREE.Vector2(0.42, -0.24),
    new THREE.Vector2(0.34, -0.1),
    new THREE.Vector2(0.31, 0.02),
    new THREE.Vector2(0.34, 0.14),
    new THREE.Vector2(0.4, 0.25),
    new THREE.Vector2(0.46, 0.34),
    new THREE.Vector2(0.46, 0.42),
    new THREE.Vector2(0.4, 0.49),
    new THREE.Vector2(0.28, 0.55),
    new THREE.Vector2(0.17, 0.6),
    new THREE.Vector2(0.135, 0.67),
    new THREE.Vector2(0.13, 0.76),
  ]).getPoints(64);

  const torso = new THREE.Mesh(new THREE.LatheGeometry(torsoProfile, 72), chrome);
  torso.scale.z = 0.64;
  body.add(torso);

  // chest forms
  const chestGeo = new THREE.SphereGeometry(0.145, 32, 24);
  for (const side of [-1, 1]) {
    const chest = new THREE.Mesh(chestGeo, chrome);
    chest.position.set(side * 0.15, 0.21, 0.17);
    chest.scale.set(1.0, 0.92, 0.78);
    body.add(chest);
  }

  const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.105, 0.125, 0.32, 32), chrome);
  neck.position.y = 0.84;
  body.add(neck);

  // head
  const head = new THREE.Group();
  head.position.y = 1.18;
  body.add(head);

  const skull = new THREE.Mesh(new THREE.SphereGeometry(0.3, 48, 36), chrome);
  skull.scale.set(0.84, 1.06, 0.92);
  head.add(skull);

  const visor = new THREE.Mesh(new THREE.SphereGeometry(0.3, 40, 28), darkGlass);
  visor.scale.set(0.68, 0.85, 0.42);
  visor.position.set(0, -0.015, 0.18);
  head.add(visor);

  const eyeMat = new THREE.MeshBasicMaterial({ color: palette.eye, toneMapped: false });
  const eyeGeo = new THREE.SphereGeometry(0.05, 20, 12);
  const eyeGlows = [];
  for (const side of [-1, 1]) {
    const eye = new THREE.Mesh(eyeGeo, eyeMat);
    eye.position.set(side * 0.088, 0.045, 0.288);
    eye.scale.set(1.25, 0.3, 0.22);
    eye.rotation.z = side * -0.09;
    head.add(eye);
    const glow = makeGlowSprite(palette.eye, 0.3, 0.7);
    glow.position.copy(eye.position);
    head.add(glow);
    eyeGlows.push(glow);
  }

  const mouth = new THREE.Mesh(new THREE.SphereGeometry(0.05, 16, 10), new THREE.MeshBasicMaterial({ color: 0xff6fa8, toneMapped: false }));
  mouth.position.set(0, -0.13, 0.286);
  mouth.scale.set(0.7, 0.13, 0.18);
  head.add(mouth);

  const browMat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.5, toneMapped: false });
  for (const side of [-1, 1]) {
    const brow = new THREE.Mesh(new THREE.CapsuleGeometry(0.006, 0.075, 4, 8), browMat);
    brow.position.set(side * 0.092, 0.1, 0.282);
    brow.rotation.z = Math.PI / 2 + side * 0.16;
    head.add(brow);
  }

  const thirdEye = new THREE.Mesh(
    new THREE.OctahedronGeometry(0.035, 0),
    new THREE.MeshBasicMaterial({ color: palette.skyAccent, toneMapped: false })
  );
  thirdEye.position.set(0, 0.16, 0.268);
  thirdEye.scale.set(1, 1.35, 0.5);
  head.add(thirdEye);

  const gemMat = new THREE.MeshBasicMaterial({ color: palette.skyAccent, toneMapped: false });
  const cheekGemGeo = new THREE.OctahedronGeometry(0.012, 0);
  const cheekSpots = [
    [0.15, 0.02, 0.252],
    [0.185, -0.03, 0.235],
    [0.13, -0.07, 0.262],
  ];
  cheekSpots.forEach(([x, y, z], i) => {
    const gem = new THREE.Mesh(cheekGemGeo, gemMat);
    gem.position.set(x, y, z);
    gem.scale.setScalar(i === 1 ? 0.8 : 1);
    head.add(gem);
  });

  // crown
  const crown = new THREE.Group();
  crown.position.y = 1.5;
  head.add(crown);
  crown.position.y = 0.32;

  const crownRing = new THREE.Mesh(new THREE.TorusGeometry(0.29, 0.012, 8, 90), chrome);
  crownRing.rotation.x = Math.PI / 2;
  crown.add(crownRing);

  const spikeGeo = new THREE.ConeGeometry(0.021, 1, 5);
  const crownGemGeo = new THREE.OctahedronGeometry(0.026, 0);
  for (let i = 0; i < 9; i++) {
    const a = (i / 9) * Math.PI * 2;
    const h = 0.1 + Math.abs(Math.sin(a * 1.5)) * 0.18 + (i === 0 ? 0.1 : 0);
    const spike = new THREE.Mesh(spikeGeo, chrome);
    spike.scale.y = h;
    spike.position.set(Math.cos(a) * 0.29, h * 0.5, Math.sin(a) * 0.29);
    spike.rotation.z = Math.cos(a) * -0.16;
    spike.rotation.x = Math.sin(a) * 0.16;
    crown.add(spike);
    if (i % 3 === 0) {
      const gem = new THREE.Mesh(crownGemGeo, gemMat);
      gem.position.set(Math.cos(a) * 0.29, h + 0.02, Math.sin(a) * 0.29);
      crown.add(gem);
    }
  }

  const crownGem = new THREE.Mesh(new THREE.OctahedronGeometry(0.045, 0), new THREE.MeshBasicMaterial({ color: palette.skyMid, toneMapped: false }));
  crownGem.position.set(0, 0.03, 0.3);
  crownGem.scale.set(1, 1.4, 0.7);
  crown.add(crownGem);

  // hair
  const hairMat = new THREE.ShaderMaterial({
    uniforms: {
      uTime: { value: 0 },
      uColorA: { value: current.hairA.clone() },
      uColorB: { value: current.hairB.clone() },
      uColorC: { value: current.hairC.clone() },
      uOpacity: { value: 0.92 },
    },
    vertexShader: hairVertex,
    fragmentShader: hairFragment,
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    side: THREE.DoubleSide,
    toneMapped: false,
  });
  const hair = new THREE.Group();
  const strandCount = 24;
  for (let i = 0; i < strandCount; i++) {
    const a = (i / strandCount) * Math.PI * 2;
    const x = Math.sin(a) * 0.29;
    const z = Math.cos(a) * 0.26;
    if (z > 0.1 && Math.abs(x) < 0.25) continue;
    const rootY = 1.4 - Math.max(0, z) * 0.12;
    const len = 0.9 + Math.random() * 0.55;
    const points = [
      [x * 0.72, rootY, z * 0.72],
      [x * 1.08, rootY - 0.16, z * 1.02 - 0.02],
      [x * 1.38 + rand(-0.06, 0.06), rootY - 0.46, z * 1.18 - 0.08],
      [x * 1.55 + rand(-0.08, 0.08), rootY - 0.86, z * 1.12 - 0.16],
      [x * 1.4 + rand(-0.1, 0.1), rootY - 1.26, z * 0.94 - 0.2],
      [x * 1.2 + rand(-0.12, 0.12), rootY - 1.26 - len * 0.5, z * 0.78 - 0.18],
    ];
    const width = 0.035 + Math.random() * 0.05;
    const strand = new THREE.Mesh(ribbonGeometry(points, width, 46), hairMat);
    strand.renderOrder = 2;
    hair.add(strand);
  }
  body.add(hair);

  // halo rings
  const haloGroup = new THREE.Group();
  haloGroup.position.y = 1.58;
  body.add(haloGroup);
  const haloMats = [];
  const haloSpecs = [
    [0.6, 0.011, 1.28, 0.14, 0.9],
    [0.8, 0.008, 1.02, -0.22, 0.7],
    [1.0, 0.005, 1.5, 0.35, 0.4],
  ];
  const haloRings = [];
  haloSpecs.forEach(([radius, tube, rx, rz, opacity]) => {
    const mat = makeHaloMaterial(palette.halo, palette.skyAccent, opacity);
    const ring = new THREE.Mesh(new THREE.TorusGeometry(radius, tube, 6, 180), mat);
    ring.rotation.x = rx;
    ring.rotation.z = rz;
    haloGroup.add(ring);
    haloMats.push(mat);
    haloRings.push(ring);
  });

  const bodyRing = new THREE.Mesh(new THREE.TorusGeometry(0.98, 0.005, 6, 160), makeHaloMaterial(palette.skyMid, palette.skyAccent, 0.4));
  bodyRing.rotation.x = Math.PI / 2;
  bodyRing.position.y = 0.06;
  body.add(bodyRing);
  haloMats.push(bodyRing.material);

  const haloGlow = makeGlowSprite(palette.halo, 2.4, 0.18);
  haloGlow.position.y = 1.62;
  body.add(haloGlow);

  // heart
  const heartMat = new THREE.MeshBasicMaterial({ color: palette.heart, toneMapped: false });
  const heart = new THREE.Mesh(new THREE.OctahedronGeometry(0.1, 0), heartMat);
  heart.position.set(0, 0.19, 0.245);
  heart.scale.set(0.8, 1.15, 0.6);
  body.add(heart);
  const heartGlow = makeGlowSprite(palette.heart, 0.95, 0.85);
  heartGlow.position.copy(heart.position);
  body.add(heartGlow);
  const heartLight = new THREE.PointLight(palette.heart, 12, 4.5, 2);
  heartLight.position.set(0, 0.2, 0.42);
  body.add(heartLight);

  // arms
  const armMat = chrome;
  const rightCurve = new THREE.CatmullRomCurve3([
    new THREE.Vector3(0.41, 0.44, 0),
    new THREE.Vector3(0.6, 0.52, 0.03),
    new THREE.Vector3(0.73, 0.7, 0.09),
    new THREE.Vector3(0.79, 0.88, 0.15),
  ]);
  const leftCurve = new THREE.CatmullRomCurve3([
    new THREE.Vector3(-0.41, 0.44, 0),
    new THREE.Vector3(-0.6, 0.29, 0.06),
    new THREE.Vector3(-0.71, 0.04, 0.13),
    new THREE.Vector3(-0.77, -0.22, 0.18),
  ]);

  for (const [curve, side] of [
    [rightCurve, 1],
    [leftCurve, -1],
  ]) {
    const arm = new THREE.Mesh(new THREE.TubeGeometry(curve, 36, 0.072, 12, false), armMat);
    body.add(arm);
    const shoulder = new THREE.Mesh(new THREE.SphereGeometry(0.145, 24, 18), armMat);
    shoulder.position.set(side * 0.42, 0.44, 0);
    shoulder.scale.set(1.05, 0.9, 0.9);
    body.add(shoulder);
    const elbow = new THREE.Mesh(new THREE.SphereGeometry(0.076, 18, 14), armMat);
    elbow.position.copy(curve.getPoint(0.55));
    body.add(elbow);
    const wrist = new THREE.Mesh(new THREE.SphereGeometry(0.06, 16, 12), armMat);
    wrist.position.copy(curve.getPoint(0.94));
    body.add(wrist);
  }

  const rightHand = new THREE.Mesh(new THREE.SphereGeometry(0.095, 24, 18), armMat);
  rightHand.position.set(0.8, 0.93, 0.16);
  rightHand.scale.set(0.95, 1.35, 0.65);
  rightHand.rotation.z = -0.5;
  body.add(rightHand);

  const leftHand = new THREE.Mesh(new THREE.SphereGeometry(0.085, 24, 18), armMat);
  leftHand.position.set(-0.785, -0.28, 0.19);
  leftHand.scale.set(0.85, 1.5, 0.6);
  leftHand.rotation.z = 0.25;
  body.add(leftHand);

  const fingertipMat = new THREE.MeshBasicMaterial({ color: palette.eye, toneMapped: false });
  const fingertipGeo = new THREE.SphereGeometry(0.014, 10, 8);
  const fingertipPositions = [
    [0.84, 1.02, 0.17],
    [0.87, 0.99, 0.15],
    [0.8, 0.99, 0.2],
    [0.75, 1.0, 0.14],
    [-0.8, -0.39, 0.2],
    [-0.75, -0.4, 0.22],
    [-0.84, -0.4, 0.18],
  ];
  fingertipPositions.forEach(([x, y, z]) => {
    const tip = new THREE.Mesh(fingertipGeo, fingertipMat);
    tip.position.set(x, y, z);
    body.add(tip);
  });

  // hand orb
  const orbMat = new THREE.MeshBasicMaterial({ color: 0xffffff, toneMapped: false });
  const handOrb = new THREE.Mesh(new THREE.SphereGeometry(0.06, 24, 18), orbMat);
  handOrb.position.set(0.83, 1.14, 0.2);
  body.add(handOrb);
  const orbGlow = makeGlowSprite(palette.skyAccent, 0.8, 0.9);
  orbGlow.position.copy(handOrb.position);
  body.add(orbGlow);
  const orbRingMat = makeHaloMaterial(palette.skyAccent, palette.halo, 0.8);
  const orbRing = new THREE.Mesh(new THREE.TorusGeometry(0.13, 0.004, 6, 80), orbRingMat);
  orbRing.position.copy(handOrb.position);
  orbRing.rotation.x = 1.2;
  body.add(orbRing);

  // gown
  const gownProfile = new THREE.SplineCurve([
    new THREE.Vector2(0.3, 0.04),
    new THREE.Vector2(0.33, -0.12),
    new THREE.Vector2(0.4, -0.36),
    new THREE.Vector2(0.52, -0.64),
    new THREE.Vector2(0.68, -0.94),
    new THREE.Vector2(0.88, -1.26),
    new THREE.Vector2(1.02, -1.48),
  ]).getPoints(48);
  const gownGeo = new THREE.LatheGeometry(gownProfile, 96);
  gownGeo.scale(1, 1, 0.82);
  const gownMat = new THREE.ShaderMaterial({
    uniforms: {
      uTime: { value: 0 },
      uColorA: { value: current.dressA.clone() },
      uColorB: { value: current.dressB.clone() },
      uColorC: { value: current.dressC.clone() },
      uOpacity: { value: 1 },
    },
    vertexShader: clothVertex,
    fragmentShader: clothFragment,
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    side: THREE.DoubleSide,
    toneMapped: false,
  });
  const gown = new THREE.Mesh(gownGeo, gownMat);
  gown.renderOrder = 3;
  body.add(gown);

  const innerGown = new THREE.Mesh(
    new THREE.LatheGeometry(
      new THREE.SplineCurve([
        new THREE.Vector2(0.27, 0.0),
        new THREE.Vector2(0.31, -0.2),
        new THREE.Vector2(0.4, -0.5),
        new THREE.Vector2(0.52, -0.9),
        new THREE.Vector2(0.62, -1.25),
      ]).getPoints(32),
      64
    ),
    new THREE.MeshPhysicalMaterial({
      color: 0x2a0c3f,
      metalness: 0.8,
      roughness: 0.15,
      transparent: true,
      opacity: 0.5,
      side: THREE.DoubleSide,
      depthWrite: false,
      envMapIntensity: 1.2,
    })
  );
  innerGown.scale.z = 0.82;
  innerGown.renderOrder = 1;
  body.add(innerGown);

  // cape
  const capeGeo = new THREE.PlaneGeometry(1.45, 2.5, 28, 44);
  const capeMat = new THREE.ShaderMaterial({
    uniforms: {
      uTime: { value: 0 },
      uColorA: { value: current.dressA.clone() },
      uColorB: { value: current.dressB.clone() },
      uColorC: { value: current.dressC.clone() },
      uOpacity: { value: 0.85 },
    },
    vertexShader: clothVertex,
    fragmentShader: capeFragment,
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    side: THREE.DoubleSide,
    toneMapped: false,
  });
  const cape = new THREE.Mesh(capeGeo, capeMat);
  cape.position.set(0, 0.28, -0.36);
  cape.rotation.x = -0.06;
  cape.renderOrder = 0;
  body.add(cape);

  // orbiting gems
  const gemCount = 18;
  const gemMesh = new THREE.InstancedMesh(
    new THREE.OctahedronGeometry(0.032, 0),
    new THREE.MeshBasicMaterial({ toneMapped: false }),
    gemCount
  );
  gemMesh.frustumCulled = false;
  body.add(gemMesh);
  const gemData = [];
  for (let i = 0; i < gemCount; i++) {
    gemData.push({
      radius: rand(0.95, 1.55),
      y: rand(-0.15, 1.45),
      phase: rand(0, Math.PI * 2),
      speed: rand(0.15, 0.4) * (Math.random() > 0.5 ? 1 : -1),
      scale: rand(0.55, 1.4),
      bob: rand(0.05, 0.2),
    });
    gemMesh.setColorAt(i, i % 3 === 0 ? target.gemC : i % 3 === 1 ? target.gemA : target.gemB);
  }
  gemMesh.instanceColor.needsUpdate = true;

  let time = 0;
  let destruction = 0;
  let morph = 0;
  let creation = 0;
  let pointerX = 0;
  let pointerY = 0;
  const dummy = new THREE.Object3D();
  const red = new THREE.Color(0xff2444);
  const tmpColor = new THREE.Color();

  function setPalette(p) {
    target.hairA.set(p.hairA);
    target.hairB.set(p.hairB);
    target.hairC.set(p.hairC);
    target.dressA.set(p.dressA);
    target.dressB.set(p.dressB);
    target.dressC.set(p.dressC);
    target.heart.set(p.heart);
    target.haloA.set(p.halo);
    target.haloB.set(p.skyAccent);
    target.eye.set(p.eye);
    target.gemA.set(p.skyMid);
    target.gemB.set(p.skyAccent);
    fingertipMat.color.set(p.eye);
  }

  function react(power) {
    if (power === "destroy") destruction = 1;
    if (power === "change") morph = 1;
    if (power === "create") creation = 1;
  }

  function update(dt, elapsed, pointer = { x: 0, y: 0 }) {
    time = elapsed;
    pointerX += (pointer.x - pointerX) * Math.min(1, dt * 3);
    pointerY += (pointer.y - pointerY) * Math.min(1, dt * 3);
    destruction = Math.max(0, destruction - dt * 0.5);
    creation = Math.max(0, creation - dt * 0.6);
    morph = Math.max(0, morph - dt * 2.2);

    const k = 1 - Math.exp(-2.6 * dt);
    current.hairA.lerp(target.hairA, k);
    current.hairB.lerp(target.hairB, k);
    current.hairC.lerp(target.hairC, k);
    current.dressA.lerp(target.dressA, k);
    current.dressB.lerp(target.dressB, k);
    current.dressC.lerp(target.dressC, k);
    current.heart.lerp(target.heart, k);
    current.haloA.lerp(target.haloA, k);
    current.haloB.lerp(target.haloB, k);
    current.eye.lerp(target.eye, k);
    current.gemA.lerp(target.gemA, k);
    current.gemB.lerp(target.gemB, k);

    const destroyEase = destruction * destruction;
    const eyeColor = tmpColor.copy(current.eye).lerp(red, destroyEase);
    eyeMat.color.copy(eyeColor);
    fingertipMat.color.copy(eyeColor);
    heartMat.color.copy(tmpColor.copy(current.heart).lerp(red, destroyEase));
    heartGlow.material.color.copy(heartMat.color);
    heartLight.color.copy(heartMat.color);
    orbMat.color.copy(tmpColor.copy(current.eye).lerp(red, destroyEase * 0.7));
    orbGlow.material.color.copy(tmpColor.copy(current.haloB).lerp(red, destroyEase * 0.7));

    hairMat.uniforms.uColorA.value.copy(current.hairA);
    hairMat.uniforms.uColorB.value.copy(current.hairB);
    hairMat.uniforms.uColorC.value.copy(current.hairC);
    hairMat.uniforms.uTime.value = time;

    gownMat.uniforms.uColorA.value.copy(current.dressA);
    gownMat.uniforms.uColorB.value.copy(current.dressB);
    gownMat.uniforms.uColorC.value.copy(current.dressC);
    gownMat.uniforms.uTime.value = time;

    capeMat.uniforms.uColorA.value.copy(current.dressA);
    capeMat.uniforms.uColorB.value.copy(current.dressB);
    capeMat.uniforms.uColorC.value.copy(current.dressC);
    capeMat.uniforms.uTime.value = time;

    haloMats.forEach((mat) => {
      mat.uniforms.uColorA.value.copy(current.haloA);
      mat.uniforms.uColorB.value.copy(current.haloB);
      mat.uniforms.uTime.value = time;
    });
    orbRingMat.uniforms.uColorA.value.copy(current.gemB);
    orbRingMat.uniforms.uColorB.value.copy(current.haloA);
    orbRingMat.uniforms.uTime.value = time;

    gemData.forEach((g, i) => {
      gemMesh.setColorAt(i, i % 3 === 0 ? current.gemC : i % 3 === 1 ? current.gemA : current.gemB);
    });
    gemMesh.instanceColor.needsUpdate = true;

    root.position.y = 0.14 + Math.sin(time * 0.7) * 0.045 + creation * 0.04;
    body.rotation.y = Math.sin(time * 0.28) * 0.07 + pointerX * 0.08;
    body.rotation.z = Math.sin(time * 0.42) * 0.012 + destruction * Math.sin(time * 38) * 0.006;
    body.rotation.x = pointerY * 0.02;

    const squash = morph * 0.07;
    body.scale.set(1 + squash, 1 - squash * 0.75, 1 + squash);

    head.rotation.y = Math.sin(time * 0.36) * 0.08 + pointerX * 0.16;
    head.rotation.z = Math.sin(time * 0.52) * 0.02 + destruction * Math.sin(time * 23) * 0.02;
    head.rotation.x = pointerY * 0.05;

    haloRings[0].rotation.z += dt * (0.35 + destruction * 1.6);
    haloRings[1].rotation.z -= dt * (0.22 + destruction * 1.1);
    haloRings[2].rotation.y += dt * 0.14;
    bodyRing.rotation.z += dt * 0.12;
    haloGlow.material.opacity = 0.14 + Math.sin(time * 1.4) * 0.05 + creation * 0.1;
    haloGlow.scale.setScalar(2.4 + Math.sin(time * 1.1) * 0.12 + creation * 0.5);

    heart.scale.set(0.8 + Math.sin(time * 2.2) * 0.08 + creation * 0.18, 1.15 + Math.sin(time * 2.2) * 0.1, 0.6);
    heart.rotation.y += dt * 0.7;
    heartGlow.material.opacity = 0.6 + Math.sin(time * 2.2) * 0.2 + creation * 0.2;
    heartGlow.scale.setScalar(0.95 + Math.sin(time * 2.2) * 0.1 + creation * 0.4);
    heartLight.intensity = 10 + Math.sin(time * 2.2) * 4 + creation * 12;

    handOrb.position.y = 1.14 + Math.sin(time * 1.5) * 0.035 + creation * 0.05;
    handOrb.scale.setScalar(1 + Math.sin(time * 2.4) * 0.08 + creation * 0.5);
    orbGlow.position.copy(handOrb.position);
    orbGlow.scale.setScalar(0.8 + Math.sin(time * 2.1) * 0.08 + creation * 0.7);
    orbRing.position.copy(handOrb.position);
    orbRing.rotation.z += dt * 0.8;
    orbRing.rotation.x = 1.2 + Math.sin(time * 0.7) * 0.3;

    eyeGlows.forEach((glow, i) => {
      glow.material.opacity = 0.5 + Math.sin(time * 2.6 + i) * 0.18 + destruction * 0.4;
      glow.scale.setScalar(0.3 + Math.sin(time * 2.1 + i) * 0.03 + creation * 0.1);
    });

    gemData.forEach((g, i) => {
      const a = g.phase + time * g.speed;
      dummy.position.set(Math.cos(a) * g.radius, g.y + Math.sin(time * 0.8 + g.phase) * g.bob, Math.sin(a) * g.radius);
      dummy.rotation.set(time * 0.8 + i, time * 0.6 + i * 0.3, 0);
      dummy.scale.setScalar(g.scale * (1 + Math.sin(time * 1.7 + g.phase) * 0.15));
      dummy.updateMatrix();
      gemMesh.setMatrixAt(i, dummy.matrix);
    });
    gemMesh.instanceMatrix.needsUpdate = true;

    thirdEye.rotation.y += dt * 0.7;
    crownGem.rotation.y -= dt * 0.5;
  }

  return { root, body, head, setPalette, react, update, materials: { chrome, darkGlass }, haloGlow };
}

import * as THREE from "three";
import { mergeGeometries } from "three/addons/utils/BufferGeometryUtils.js";
import { rand, easeOutCubic } from "./utils.js";

const particleVertex = /* glsl */ `
  attribute float aSize;
  attribute float aAlpha;
  attribute vec3 aColor;
  varying vec3 vColor;
  varying float vAlpha;
  void main() {
    vColor = aColor;
    vAlpha = aAlpha;
    vec4 mv = modelViewMatrix * vec4(position, 1.0);
    gl_PointSize = aSize * (360.0 / max(0.1, -mv.z));
    gl_Position = projectionMatrix * mv;
  }
`;

const particleFragment = /* glsl */ `
  varying vec3 vColor;
  varying float vAlpha;
  void main() {
    float d = length(gl_PointCoord - 0.5);
    if (d > 0.5) discard;
    float a = smoothstep(0.5, 0.0, d);
    gl_FragColor = vec4(vColor, a * vAlpha);
  }
`;

class ParticleField {
  constructor(group) {
    this.max = 900;
    this.cursor = 0;
    this.positions = new Float32Array(this.max * 3);
    this.colors = new Float32Array(this.max * 3);
    this.sizes = new Float32Array(this.max);
    this.alphas = new Float32Array(this.max);
    this.velocities = new Float32Array(this.max * 3);
    this.lives = new Float32Array(this.max);
    this.maxLives = new Float32Array(this.max);
    this.drags = new Float32Array(this.max);
    this.gravities = new Float32Array(this.max);

    const geo = new THREE.BufferGeometry();
    geo.setAttribute("position", new THREE.BufferAttribute(this.positions, 3).setUsage(THREE.DynamicDrawUsage));
    geo.setAttribute("aColor", new THREE.BufferAttribute(this.colors, 3).setUsage(THREE.DynamicDrawUsage));
    geo.setAttribute("aSize", new THREE.BufferAttribute(this.sizes, 1).setUsage(THREE.DynamicDrawUsage));
    geo.setAttribute("aAlpha", new THREE.BufferAttribute(this.alphas, 1).setUsage(THREE.DynamicDrawUsage));

    this.material = new THREE.ShaderMaterial({
      vertexShader: particleVertex,
      fragmentShader: particleFragment,
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      toneMapped: false,
    });
    this.points = new THREE.Points(geo, this.material);
    this.points.frustumCulled = false;
    group.add(this.points);
    this.geo = geo;
    this.tmp = new THREE.Color();
  }

  burst(origin, count, palette, opts = {}) {
    const {
      speed = 3.2,
      spread = 0.12,
      gravity = 0.8,
      drag = 0.986,
      size = 1,
      life = 1.4,
      paletteMix = true,
      colors = null,
    } = opts;
    const paletteColors = [
      new THREE.Color(palette.skyMid),
      new THREE.Color(palette.skyAccent),
      new THREE.Color(palette.halo),
      new THREE.Color(palette.heart),
      new THREE.Color(0xffffff),
    ];
    for (let n = 0; n < count; n++) {
      const i = this.cursor;
      this.cursor = (this.cursor + 1) % this.max;
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(rand(-1, 1));
      const dirX = Math.sin(phi) * Math.cos(theta);
      const dirY = Math.cos(phi);
      const dirZ = Math.sin(phi) * Math.sin(theta);
      const s = speed * rand(0.35, 1.15);
      this.positions[i * 3] = origin.x + dirX * spread;
      this.positions[i * 3 + 1] = origin.y + dirY * spread;
      this.positions[i * 3 + 2] = origin.z + dirZ * spread;
      this.velocities[i * 3] = dirX * s;
      this.velocities[i * 3 + 1] = dirY * s + rand(0.2, 1.4);
      this.velocities[i * 3 + 2] = dirZ * s;
      const c = colors && colors.length
        ? new THREE.Color(colors[Math.floor(Math.random() * colors.length)])
        : paletteMix
          ? paletteColors[Math.floor(Math.random() * paletteColors.length)]
          : new THREE.Color(0xffffff);
      this.colors[i * 3] = c.r;
      this.colors[i * 3 + 1] = c.g;
      this.colors[i * 3 + 2] = c.b;
      this.sizes[i] = rand(0.035, 0.16) * size;
      const l = life * rand(0.55, 1.25);
      this.lives[i] = l;
      this.maxLives[i] = l;
      this.alphas[i] = 1;
      this.drags[i] = drag;
      this.gravities[i] = gravity;
    }
    this.geo.attributes.position.needsUpdate = true;
    this.geo.attributes.aColor.needsUpdate = true;
    this.geo.attributes.aSize.needsUpdate = true;
    this.geo.attributes.aAlpha.needsUpdate = true;
  }

  update(dt) {
    for (let i = 0; i < this.max; i++) {
      if (this.lives[i] <= 0) {
        if (this.alphas[i] !== 0) this.alphas[i] = 0;
        continue;
      }
      this.lives[i] -= dt;
      const drag = Math.pow(this.drags[i], dt * 60);
      this.velocities[i * 3] *= drag;
      this.velocities[i * 3 + 1] = this.velocities[i * 3 + 1] * drag - this.gravities[i] * dt;
      this.velocities[i * 3 + 2] *= drag;
      this.positions[i * 3] += this.velocities[i * 3] * dt;
      this.positions[i * 3 + 1] += this.velocities[i * 3 + 1] * dt;
      this.positions[i * 3 + 2] += this.velocities[i * 3 + 2] * dt;
      const lifeRatio = Math.max(0, this.lives[i] / this.maxLives[i]);
      this.alphas[i] = Math.min(1, lifeRatio * 1.8) * 0.95;
    }
    this.geo.attributes.position.needsUpdate = true;
    this.geo.attributes.aAlpha.needsUpdate = true;
  }
}

class Shockwaves {
  constructor(group, camera) {
    this.camera = camera;
    this.items = [];
    for (let i = 0; i < 8; i++) {
      const material = new THREE.MeshBasicMaterial({
        color: 0xffffff,
        transparent: true,
        opacity: 0,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        side: THREE.DoubleSide,
        toneMapped: false,
      });
      const mesh = new THREE.Mesh(new THREE.RingGeometry(0.86, 1, 96), material);
      mesh.visible = false;
      mesh.frustumCulled = false;
      group.add(mesh);
      this.items.push({ mesh, active: false, t: 0, dur: 1, scale: 1, faceCamera: false, baseOpacity: 1 });
    }
  }

  spawn(position, color, opts = {}) {
    const item = this.items.find((i) => !i.active) || this.items[0];
    const { duration = 0.9, scale = 4, faceCamera = false, opacity = 0.9, startScale = 0.15 } = opts;
    item.active = true;
    item.t = 0;
    item.dur = duration;
    item.scale = scale;
    item.startScale = startScale;
    item.faceCamera = faceCamera;
    item.baseOpacity = opacity;
    item.mesh.visible = true;
    item.mesh.position.copy(position);
    item.mesh.material.color.set(color);
    item.mesh.material.opacity = opacity;
    if (faceCamera) {
      item.mesh.rotation.set(0, 0, 0);
      item.mesh.quaternion.copy(this.camera.quaternion);
    } else {
      item.mesh.quaternion.identity();
      item.mesh.rotation.x = -Math.PI / 2;
    }
  }

  update(dt) {
    this.items.forEach((item) => {
      if (!item.active) return;
      item.t += dt;
      const p = Math.min(1, item.t / item.dur);
      const e = easeOutCubic(p);
      const s = item.startScale + e * item.scale;
      item.mesh.scale.setScalar(s);
      item.mesh.material.opacity = (1 - p) * item.baseOpacity;
      if (item.faceCamera) item.mesh.quaternion.copy(this.camera.quaternion);
      if (p >= 1) {
        item.active = false;
        item.mesh.visible = false;
      }
    });
  }
}

class ShardBurst {
  constructor(group, palette) {
    this.count = 110;
    this.data = [];
    this.material = new THREE.MeshStandardMaterial({
      color: 0xffffff,
      metalness: 0.9,
      roughness: 0.18,
      envMapIntensity: 1.4,
      emissive: 0x12000a,
      emissiveIntensity: 0.6,
    });
    this.mesh = new THREE.InstancedMesh(new THREE.TetrahedronGeometry(0.085, 0), this.material, this.count);
    this.mesh.frustumCulled = false;
    this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    group.add(this.mesh);
    const dummy = new THREE.Object3D();
    dummy.scale.setScalar(0.001);
    dummy.updateMatrix();
    for (let i = 0; i < this.count; i++) {
      this.mesh.setMatrixAt(i, dummy.matrix);
      this.data.push({
        active: false,
        pos: new THREE.Vector3(),
        vel: new THREE.Vector3(),
        rot: new THREE.Euler(),
        rotVel: new THREE.Vector3(),
        scale: 1,
        life: 0,
        maxLife: 1,
      });
    }
    this.dummy = new THREE.Object3D();
    this.palette = palette;
  }

  burst(origin, palette) {
    this.palette = palette;
    const colors = [new THREE.Color(palette.skyMid), new THREE.Color(palette.skyAccent), new THREE.Color(palette.halo), new THREE.Color(0xffffff)];
    this.data.forEach((d, i) => {
      d.active = true;
      d.pos.copy(origin).add(new THREE.Vector3(rand(-0.9, 0.9), rand(-0.6, 1.1), rand(-0.6, 0.6)));
      const dir = d.pos.clone().sub(origin).normalize();
      const speed = rand(1.6, 6.5);
      d.vel.set(dir.x * speed + rand(-1, 1), rand(0.5, 4.5), dir.z * speed + rand(-1, 1));
      d.rot.set(rand(0, 6), rand(0, 6), rand(0, 6));
      d.rotVel.set(rand(-8, 8), rand(-8, 8), rand(-8, 8));
      d.scale = rand(0.5, 1.8);
      d.maxLife = rand(1.4, 2.8);
      d.life = d.maxLife;
      this.mesh.setColorAt(i, colors[Math.floor(Math.random() * colors.length)]);
    });
    if (this.mesh.instanceColor) this.mesh.instanceColor.needsUpdate = true;
  }

  update(dt) {
    this.data.forEach((d, i) => {
      if (!d.active) return;
      d.life -= dt;
      if (d.life <= 0) {
        d.active = false;
        this.dummy.position.set(0, -999, 0);
        this.dummy.scale.setScalar(0.001);
        this.dummy.rotation.set(0, 0, 0);
        this.dummy.updateMatrix();
        this.mesh.setMatrixAt(i, this.dummy.matrix);
        return;
      }
      d.vel.y -= 5.2 * dt;
      d.pos.addScaledVector(d.vel, dt);
      d.rot.x += d.rotVel.x * dt;
      d.rot.y += d.rotVel.y * dt;
      d.rot.z += d.rotVel.z * dt;
      const fade = Math.min(1, d.life / 0.45);
      this.dummy.position.copy(d.pos);
      this.dummy.rotation.copy(d.rot);
      this.dummy.scale.setScalar(d.scale * fade);
      this.dummy.updateMatrix();
      this.mesh.setMatrixAt(i, this.dummy.matrix);
    });
    this.mesh.instanceMatrix.needsUpdate = true;
  }
}

function buildFlowerGeometries() {
  const stemParts = [];
  const stem = new THREE.CylinderGeometry(0.012, 0.02, 0.44, 6);
  stem.translate(0, 0.22, 0);
  stemParts.push(stem);

  for (const side of [-1, 1]) {
    const leaf = new THREE.SphereGeometry(0.09, 8, 6);
    leaf.scale(1.2, 0.16, 0.45);
    leaf.rotateZ(side * 0.55);
    leaf.translate(side * 0.08, 0.16 + (side > 0 ? 0.08 : 0.02), 0);
    stemParts.push(leaf);
  }

  const petalParts = [];
  const petalCount = 6;
  const tilt = new THREE.Matrix4().makeRotationX(-0.5);
  for (let i = 0; i < petalCount; i++) {
    const a = (i / petalCount) * Math.PI * 2;
    const petal = new THREE.SphereGeometry(0.1, 10, 8);
    petal.scale(1.35, 0.24, 0.6);
    const m = new THREE.Matrix4();
    const rot = new THREE.Matrix4().makeRotationY(a);
    const trans = new THREE.Matrix4().makeTranslation(0.105, 0, 0);
    m.multiply(rot).multiply(trans);
    petal.applyMatrix4(m);
    petal.applyMatrix4(tilt);
    petal.translate(0, 0.45, 0);
    petalParts.push(petal);
  }
  return {
    stem: mergeGeometries(stemParts, false),
    petals: mergeGeometries(petalParts, false),
  };
}

class FlowerField {
  constructor(group, palette) {
    this.group = group;
    this.geometries = buildFlowerGeometries();
    this.stemMaterial = new THREE.MeshStandardMaterial({
      color: 0x2f7a4a,
      roughness: 0.5,
      metalness: 0.2,
      emissive: 0x0a2a14,
      emissiveIntensity: 0.6,
    });
    this.slots = [];
    for (let i = 0; i < 16; i++) {
      const holder = new THREE.Group();
      holder.visible = false;
      const stemMesh = new THREE.Mesh(this.geometries.stem, this.stemMaterial);
      const petalMat = new THREE.MeshStandardMaterial({
        color: palette.skyMid,
        roughness: 0.25,
        metalness: 0.5,
        emissive: palette.skyMid,
        emissiveIntensity: 0.35,
        side: THREE.DoubleSide,
      });
      const petals = new THREE.Mesh(this.geometries.petals, petalMat);
      const centerMat = new THREE.MeshBasicMaterial({ color: palette.halo, toneMapped: false });
      const center = new THREE.Mesh(new THREE.SphereGeometry(0.055, 12, 8), centerMat);
      center.position.y = 0.45;
      holder.add(stemMesh, petals, center);
      group.add(holder);
      this.slots.push({
        holder,
        petalMat,
        centerMat,
        active: false,
        grow: 0,
        wither: false,
        baseScale: 1,
        phase: rand(0, 6),
        pos: new THREE.Vector3(),
        colorIndex: 0,
        age: 0,
      });
    }
    this.palette = palette;
  }

  spawn(count, palette) {
    this.palette = palette;
    let spawned = 0;
    for (const slot of this.slots) {
      if (spawned >= count) break;
      if (slot.active && !slot.wither) continue;
      const a = rand(0, Math.PI * 2);
      const r = rand(0.55, 1.28);
      slot.pos.set(Math.cos(a) * r, -1.39, Math.sin(a) * r);
      slot.holder.position.copy(slot.pos);
      slot.holder.rotation.y = rand(0, Math.PI * 2);
      slot.holder.visible = true;
      slot.active = true;
      slot.wither = false;
      slot.grow = 0.001;
      slot.age = 0;
      slot.baseScale = rand(0.6, 1.15);
      slot.phase = rand(0, 6);
      slot.colorIndex = Math.floor(Math.random() * 3);
      this.tint(slot);
      spawned++;
    }
    return spawned;
  }

  tint(slot) {
    const p = this.palette;
    const colors = [p.skyMid, p.skyAccent, p.heart, p.halo];
    slot.petalMat.color.set(colors[slot.colorIndex % colors.length]);
    slot.petalMat.emissive.set(colors[slot.colorIndex % colors.length]);
    slot.centerMat.color.set(p.halo);
  }

  setPalette(palette) {
    this.palette = palette;
    this.slots.forEach((s) => this.tint(s));
  }

  witherAll() {
    this.slots.forEach((s) => {
      if (s.active) s.wither = true;
    });
  }

  update(dt, time) {
    this.slots.forEach((s) => {
      if (!s.active) return;
      s.age += dt;
      if (s.wither) {
        s.grow -= dt * 1.8;
        if (s.grow <= 0) {
          s.grow = 0;
          s.active = false;
          s.holder.visible = false;
          return;
        }
      } else if (s.grow < 1) {
        s.grow = Math.min(1, s.grow + dt * 2.2);
      }
      const g = s.grow < 1 ? 1 - Math.pow(1 - s.grow, 3) : 1;
      const sway = Math.sin(time * 1.2 + s.phase) * 0.06;
      s.holder.scale.setScalar(s.baseScale * g);
      s.holder.rotation.z = sway * 0.5;
      s.holder.rotation.x = Math.cos(time * 0.9 + s.phase) * 0.03;
      s.holder.position.y = -1.39 + Math.sin(time * 1.4 + s.phase) * 0.008;
    });
  }
}

function wingShape() {
  const shape = new THREE.Shape();
  shape.moveTo(0, 0.02);
  shape.bezierCurveTo(0.1, 0.16, 0.24, 0.3, 0.27, 0.16);
  shape.bezierCurveTo(0.3, 0.03, 0.2, -0.1, 0.06, -0.07);
  shape.bezierCurveTo(0.02, -0.06, 0.005, -0.02, 0, 0.02);
  return shape;
}

class ButterflySwarm {
  constructor(group, palette) {
    this.palette = palette;
    this.wingGeo = new THREE.ShapeGeometry(wingShape(), 12);
    this.bodyGeo = new THREE.CapsuleGeometry(0.011, 0.075, 4, 8);
    this.bodyMat = new THREE.MeshBasicMaterial({ color: 0x1b0726, toneMapped: false });
    this.slots = [];
    for (let i = 0; i < 12; i++) {
      const holder = new THREE.Group();
      holder.visible = false;
      const body = new THREE.Mesh(this.bodyGeo, this.bodyMat);
      body.rotation.x = Math.PI / 2;
      const leftMat = new THREE.MeshBasicMaterial({
        color: palette.skyMid,
        transparent: true,
        opacity: 0.9,
        side: THREE.DoubleSide,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        toneMapped: false,
      });
      const rightMat = leftMat.clone();
      const left = new THREE.Mesh(this.wingGeo, leftMat);
      const right = new THREE.Mesh(this.wingGeo, rightMat);
      left.scale.x = -1;
      left.position.z = 0;
      holder.add(body, left, right);
      group.add(holder);
      this.slots.push({
        holder,
        left,
        right,
        leftMat,
        rightMat,
        active: false,
        grow: 0,
        fade: 1,
        radius: 1.5,
        height: 0.6,
        angle: 0,
        speed: 0.4,
        phase: rand(0, 6),
        size: 0.7,
        colorIndex: 0,
      });
    }
  }

  spawn(count, palette) {
    this.palette = palette;
    let spawned = 0;
    for (const s of this.slots) {
      if (spawned >= count) break;
      if (s.active && s.fade > 0.9) continue;
      s.active = true;
      s.holder.visible = true;
      s.grow = 0.001;
      s.fade = 1;
      s.radius = rand(1.25, 2.35);
      s.height = rand(0.1, 1.45);
      s.angle = rand(0, Math.PI * 2);
      s.speed = rand(0.3, 0.75) * (Math.random() > 0.5 ? 1 : -1);
      s.phase = rand(0, 6);
      s.size = rand(0.5, 0.95);
      s.colorIndex = Math.floor(Math.random() * 3);
      this.tint(s);
      spawned++;
    }
    return spawned;
  }

  tint(s) {
    const p = this.palette;
    const colors = [p.skyMid, p.skyAccent, p.halo, p.heart];
    const c = colors[s.colorIndex % colors.length];
    s.leftMat.color.set(c);
    s.rightMat.color.set(c);
  }

  setPalette(palette) {
    this.palette = palette;
    this.slots.forEach((s) => this.tint(s));
  }

  scatter() {
    this.slots.forEach((s) => {
      if (s.active) s.fade = 0.999;
    });
  }

  update(dt, time) {
    this.slots.forEach((s) => {
      if (!s.active) return;
      s.angle += s.speed * dt;
      if (s.fade < 1) {
        s.fade -= dt * 1.2;
        if (s.fade <= 0) {
          s.active = false;
          s.holder.visible = false;
          return;
        }
      } else if (s.grow < 1) {
        s.grow = Math.min(1, s.grow + dt * 2.5);
      }
      const r = s.radius + Math.sin(time * 0.5 + s.phase) * 0.12;
      const x = Math.cos(s.angle) * r;
      const z = Math.sin(s.angle) * r - 0.2;
      const y = s.height + Math.sin(time * 1.7 + s.phase) * 0.18;
      s.holder.position.set(x, y, z);
      s.holder.rotation.y = -s.angle + Math.PI / 2;
      s.holder.rotation.z = Math.sin(time * 1.3 + s.phase) * 0.12;
      const flap = Math.sin(time * 11 + s.phase) * 0.85 + 0.25;
      s.left.rotation.y = flap;
      s.right.rotation.y = -flap;
      const g = 1 - Math.pow(1 - s.grow, 3);
      s.holder.scale.setScalar(s.size * g * s.fade);
      s.leftMat.opacity = 0.85 * s.fade;
      s.rightMat.opacity = 0.85 * s.fade;
    });
  }
}

class Lightning {
  constructor(group) {
    this.items = [];
    for (let i = 0; i < 6; i++) {
      const geo = new THREE.BufferGeometry();
      geo.setAttribute("position", new THREE.BufferAttribute(new Float32Array(9 * 3), 3));
      const mat = new THREE.LineBasicMaterial({
        color: 0xff3b6b,
        transparent: true,
        opacity: 0,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        toneMapped: false,
      });
      const line = new THREE.Line(geo, mat);
      line.visible = false;
      line.frustumCulled = false;
      group.add(line);
      this.items.push({ line, geo, mat, active: false, t: 0, dur: 0 });
    }
  }

  strike(color) {
    this.items.forEach((item, i) => {
      const pos = item.geo.attributes.position.array;
      const startX = rand(-3.2, 3.2);
      const startZ = rand(-2.2, 0.4);
      let x = startX;
      let z = startZ;
      for (let p = 0; p < 9; p++) {
        const y = 5.2 - (p / 8) * 6.8;
        pos[p * 3] = x;
        pos[p * 3 + 1] = y;
        pos[p * 3 + 2] = z;
        x += rand(-0.4, 0.4);
        z += rand(-0.3, 0.3);
      }
      item.geo.attributes.position.needsUpdate = true;
      item.mat.color.set(color);
      item.active = true;
      item.t = 0;
      item.dur = 0.22 + Math.random() * 0.22;
      item.line.visible = true;
      item.line.position.set(0, 0, 0);
    });
  }

  update(dt) {
    this.items.forEach((item) => {
      if (!item.active) return;
      item.t += dt;
      const p = item.t / item.dur;
      item.mat.opacity = p < 1 ? (Math.random() > 0.4 ? 0.9 : 0.2) : 0;
      if (p >= 1) {
        item.active = false;
        item.line.visible = false;
      }
    });
  }
}

export class DivineEffects {
  constructor(scene, camera, palette) {
    this.group = new THREE.Group();
    scene.add(this.group);
    this.camera = camera;
    this.palette = palette;
    this.particles = new ParticleField(this.group);
    this.shockwaves = new Shockwaves(this.group, camera);
    this.shards = new ShardBurst(this.group, palette);
    this.flowers = new FlowerField(this.group, palette);
    this.butterflies = new ButterflySwarm(this.group, palette);
    this.lightning = new Lightning(this.group);
    this.origin = new THREE.Vector3(0, 0.25, 0.1);
    this.time = 0;
  }

  setPalette(palette) {
    this.palette = palette;
    this.flowers.setPalette(palette);
    this.butterflies.setPalette(palette);
  }

  create(palette, origin = this.origin) {
    this.setPalette(palette);
    this.particles.burst(origin, 170, palette, { speed: 3.4, size: 1.15, life: 1.6, gravity: 0.35 });
    this.particles.burst(new THREE.Vector3(0, -1.35, 0.3), 90, palette, {
      speed: 2.2,
      size: 0.9,
      life: 1.9,
      gravity: -0.2,
    });
    this.shockwaves.spawn(new THREE.Vector3(0, -1.36, 0), palette.skyAccent, {
      duration: 1.1,
      scale: 4.6,
      opacity: 0.8,
    });
    this.shockwaves.spawn(origin.clone().add(new THREE.Vector3(0, 0.6, 0)), palette.halo, {
      duration: 0.9,
      scale: 2.2,
      faceCamera: true,
      opacity: 0.55,
    });
    this.flowers.spawn(5, palette);
    this.butterflies.spawn(6, palette);
  }

  destroy(palette, origin = this.origin) {
    this.setPalette(palette);
    this.particles.burst(origin, 260, palette, {
      speed: 6.5,
      size: 1.5,
      life: 1.8,
      gravity: 1.4,
      colors: [0xff2b4a, 0xff8a2f, 0xffffff, palette.skyMid],
    });
    this.shards.burst(origin.clone().add(new THREE.Vector3(0, 0.25, 0)), palette);
    this.shockwaves.spawn(new THREE.Vector3(0, -1.35, 0), 0xff2b4a, {
      duration: 1.2,
      scale: 7,
      opacity: 0.95,
    });
    this.shockwaves.spawn(origin.clone().add(new THREE.Vector3(0, 0.4, 0)), 0xff5f6f, {
      duration: 0.7,
      scale: 3.4,
      faceCamera: true,
      opacity: 0.8,
    });
    this.lightning.strike(0xff4f6f);
    this.flowers.witherAll();
    this.butterflies.scatter();
  }

  change(palette, origin = this.origin) {
    this.setPalette(palette);
    this.particles.burst(origin, 150, palette, {
      speed: 3.6,
      size: 1.05,
      life: 1.4,
      gravity: 0.2,
      colors: [palette.skyAccent, palette.skyMid, 0xffffff, palette.halo],
    });
    this.shockwaves.spawn(origin.clone().add(new THREE.Vector3(0, 0.5, 0)), palette.skyAccent, {
      duration: 0.85,
      scale: 3.2,
      faceCamera: true,
      opacity: 0.7,
    });
  }

  bless(position, palette) {
    this.setPalette(palette);
    this.particles.burst(position, 70, palette, {
      speed: 2.4,
      size: 1.2,
      life: 1.2,
      gravity: 0.15,
      colors: [palette.halo, palette.skyAccent, 0xffffff],
    });
    this.shockwaves.spawn(position, palette.halo, {
      duration: 0.75,
      scale: 1.6,
      faceCamera: true,
      opacity: 0.75,
    });
  }

  update(dt, elapsed) {
    this.time = elapsed;
    this.particles.update(dt);
    this.shockwaves.update(dt);
    this.shards.update(dt);
    this.flowers.update(dt, elapsed);
    this.butterflies.update(dt, elapsed);
    this.lightning.update(dt);
  }
}

